CREATE TABLE `inventarios` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `origen` varchar(255) NOT NULL DEFAULT 'IMPORTADO',
  `item` varchar(50) NOT NULL,
  `tipo` varchar(255) NOT NULL,
  `marca` varchar(255) DEFAULT NULL,
  `modelo` varchar(255) DEFAULT NULL,
  `serial` varchar(255) DEFAULT NULL,
  `serial_image_path` varchar(255) DEFAULT NULL,
  `año` varchar(255) DEFAULT NULL,
  `codInv` varchar(255) DEFAULT NULL,
  `expediente` varchar(255) DEFAULT NULL,
  `condicion` varchar(255) DEFAULT NULL,
  `status` varchar(255) NOT NULL,
  `price` varchar(255) NOT NULL,
  `costo` decimal(10,2) DEFAULT NULL,
  `costo_importacion_unitario` decimal(15,2) NOT NULL DEFAULT 0.00,
  `prorrateo_gastos` decimal(15,2) NOT NULL DEFAULT 0.00,
  `porcentaje_utilidad` decimal(5,2) DEFAULT NULL,
  `tasa_bcv` decimal(15,4) DEFAULT NULL,
  `fecha_tasa_bcv` varchar(255) DEFAULT NULL,
  `price_sale` varchar(45) DEFAULT NULL,
  `container_id` bigint(20) unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `categorie` varchar(255) DEFAULT NULL,
  `cantidad` varchar(255) DEFAULT NULL,
  `observation` text DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `partidas_codinv_unique` (`codInv`),
  KEY `partidas_container_id_foreign` (`container_id`),
  CONSTRAINT `partidas_container_id_foreign` FOREIGN KEY (`container_id`) REFERENCES `containers` (`id`) ON DELETE CASCADE
